using System;

class Program
{
    static void Main()
    {
        // sizeof gives the size in bytes of a built-in value type
        Console.WriteLine("bool=" + sizeof(bool) + " byte=" + sizeof(byte) + " short=" + sizeof(short)
            + " int=" + sizeof(int) + " long=" + sizeof(long));
        Console.WriteLine("char=" + sizeof(char) + " float=" + sizeof(float)
            + " double=" + sizeof(double) + " decimal=" + sizeof(decimal));

        // Each whole-number type has a fixed range
        Console.WriteLine("int range: " + int.MinValue + " to " + int.MaxValue);
        Console.WriteLine("long max: " + long.MaxValue);

        // double is binary floating point: 0.1 and 0.2 are stored as close approximations
        double d = 0.1 + 0.2;
        Console.WriteLine("double 0.1 + 0.2 == 0.3 ? " + (d == 0.3) + " (value " + d.ToString("R") + ")");

        // decimal works in base 10, so money sums are exact
        decimal m = 0.1m + 0.2m;
        Console.WriteLine("decimal 0.1 + 0.2 == 0.3 ? " + (m == 0.3m) + " (value " + m + ")");

        // int is only the C# keyword for System.Int32
        Console.WriteLine("typeof(int) == typeof(Int32) ? " + (typeof(int) == typeof(Int32)));

        // By default int maths wraps around silently
        int big = int.MaxValue;
        int wrapped = unchecked(big + 1);
        Console.WriteLine("int.MaxValue + 1 = " + wrapped);
    }
}
// Time O(1), space O(1): a fixed number of operations.

using System;

struct PointStruct { public int X; }
class PointClass { public int X; }

class Program
{
    static void ChangeStruct(PointStruct p) { p.X = 500; }                   // p is a copy of the caller's struct
    static void ChangeClass(PointClass p) { p.X = 500; }                     // p points at the caller's object
    static void Replace(PointClass p) { p = new PointClass { X = 777 }; }    // only the local reference changes

    static void Main()
    {
        // Assigning a struct copies all of its data
        var a = new PointStruct { X = 1 };
        var b = a;
        b.X = 99;
        Console.WriteLine("struct: a.X=" + a.X + " b.X=" + b.X);

        // Assigning a class variable copies only the reference: one object, two names
        var c = new PointClass { X = 1 };
        var d = c;
        d.X = 99;
        Console.WriteLine("class:  c.X=" + c.X + " d.X=" + d.X + " same object? " + ReferenceEquals(c, d));

        ChangeStruct(a);
        Console.WriteLine("after ChangeStruct: a.X=" + a.X);
        ChangeClass(c);
        Console.WriteLine("after ChangeClass:  c.X=" + c.X);
        Replace(c);
        Console.WriteLine("after Replace:      c.X=" + c.X);

        // string is a reference type, but it cannot be changed, so it behaves like a value
        string s1 = "hi";
        string s2 = s1;
        s2 += "!";
        Console.WriteLine("string: s1=" + s1 + " s2=" + s2);
    }
}
// Time O(1), space O(1).

using System;
using System.Collections;
using System.Collections.Generic;

class Program
{
    static void Main()
    {
        int n = 42;
        object boxed = n;            // boxing: a new heap object gets a copy of 42
        n = 100;                     // the box is a separate copy, so it does not change
        Console.WriteLine("n=" + n + " boxed=" + boxed);

        int back = (int)boxed;       // unboxing: type check, then copy the value out
        Console.WriteLine("unboxed=" + back);

        // Unboxing must name the exact type that was boxed
        try { long bad = (long)boxed; Console.WriteLine(bad); }
        catch (InvalidCastException) { Console.WriteLine("(long)boxed -> InvalidCastException"); }
        long ok = (long)(int)boxed;  // unbox to int first, then widen
        Console.WriteLine("(long)(int)boxed=" + ok);

        // Every boxing makes a new object
        object b1 = n, b2 = n;
        Console.WriteLine("two boxes of the same int are the same object? " + ReferenceEquals(b1, b2));

        // ArrayList stores object, so each Add boxes and each read unboxes
        var old = new ArrayList();
        for (int i = 1; i <= 3; i++) old.Add(i);
        int sumOld = 0;
        foreach (object o in old) sumOld += (int)o;

        // List<int> stores the ints directly: no boxing at all
        var modern = new List<int> { 1, 2, 3 };
        int sumNew = 0;
        foreach (int x in modern) sumNew += x;
        Console.WriteLine("ArrayList sum=" + sumOld + " (3 boxes), List<int> sum=" + sumNew + " (0 boxes)");
    }
}
// Time O(n) for n items; ArrayList also allocates one heap object per item, List<int> does not.

using System;

class Program
{
    static void Main()
    {
        // var: the compiler works out the type once; here it is int for good
        var count = 5;
        Console.WriteLine("var count is " + count.GetType().Name);
        // count = "five";   // would not compile: count is an int

        // object: can hold anything, but you must cast before using the real type
        object o = "hello";
        // int len = o.Length;   // would not compile: object has no Length
        string s = (string)o;
        Console.WriteLine("object holds " + o.GetType().Name + ", length after cast = " + s.Length);

        // dynamic: member lookup happens when the line runs
        dynamic d = "hello";
        Console.WriteLine("dynamic string Length = " + d.Length);
        d = 10;                       // the same variable can now hold an int
        Console.WriteLine("dynamic int + 5 = " + (d + 5));

        // A typo compiles fine and fails only at run time
        try
        {
            d.NoSuchMethod();
        }
        catch (Microsoft.CSharp.RuntimeBinder.RuntimeBinderException)
        {
            Console.WriteLine("d.NoSuchMethod() -> RuntimeBinderException at run time");
        }
    }
}
// Time O(1), space O(1). Each dynamic call is slower than a normal call because it is resolved at run time.

using System;
using System.Text;

class Program
{
    static void Main()
    {
        // "Changing" a string makes a new one; the old one is untouched
        string a = "hello";
        string b = a;
        a += " world";
        Console.WriteLine("a=" + a + " | b=" + b);

        string upper = b.ToUpper();           // returns a new string
        Console.WriteLine("b=" + b + " | upper=" + upper);

        // Concatenating in a loop makes a new string every time: 1 + 2 + ... + n characters copied, O(n^2)
        string slow = "";
        for (int i = 1; i <= 5; i++) slow += i + ",";

        // StringBuilder appends into its own buffer: O(n) in total
        var sb = new StringBuilder();
        for (int i = 1; i <= 5; i++) sb.Append(i).Append(',');
        Console.WriteLine("concat=" + slow + " builder=" + sb + " equal? " + (slow == sb.ToString()));

        // The buffer grows when it is full
        var grow = new StringBuilder();
        Console.Write("capacity:");
        int last = -1;
        for (int i = 0; i < 40; i++)
        {
            if (grow.Capacity != last) { last = grow.Capacity; Console.Write(" " + last); }
            grow.Append('x');
        }
        Console.WriteLine();

        // Interning: equal literals share one object; a string built at run time does not
        string x = "hi";
        string y = new string(new[] { 'h', 'i' });
        Console.WriteLine("x == y ? " + (x == y) + ", same object? " + ReferenceEquals(x, y)
            + ", after Intern? " + ReferenceEquals(x, string.Intern(y)));
    }
}
// Loop concatenation: O(n^2) time. StringBuilder: O(n) time, O(n) space.

using System;
using System.Collections.Generic;

class Settings
{
    public const int MaxRetries = 3;                            // fixed at compile time, copied into callers
    public static readonly int PageSize = LoadPageSize();       // set once, at run time, shared by all objects
    public readonly int Id;                                     // set once per object, in the constructor
    public readonly List<string> Tags = new List<string>();     // the reference is fixed, the list is not

    public Settings(int id) { Id = id; }

    static int LoadPageSize()
    {
        Console.WriteLine("(static initialiser runs once)");
        return 25 * 2;      // a value that is only known when the program runs
    }

    public void TryChange()
    {
        // Id = 5;                       // would not compile: readonly, outside the constructor
        // Tags = new List<string>();    // would not compile for the same reason
        Tags.Add("changed-later");       // allowed: this changes the object, not the field
    }
}

class Program
{
    static void Main()
    {
        Console.WriteLine("const MaxRetries = " + Settings.MaxRetries);
        var a = new Settings(1);
        var b = new Settings(2);
        Console.WriteLine("static readonly PageSize = " + Settings.PageSize);
        Console.WriteLine("readonly Id: a=" + a.Id + " b=" + b.Id);

        a.Tags.Add("vip");
        a.TryChange();
        Console.WriteLine("a.Tags = [" + string.Join(", ", a.Tags) + "], b.Tags count = " + b.Tags.Count);
    }
}
// Time O(1), space O(1).

using System;

class Program
{
    static string Describe(int? age)
    {
        // HasValue tells you whether there is a number inside
        return age.HasValue ? "age " + age.Value : "age unknown";
    }

    static void Main()
    {
        int? age = null;                              // int? is short for Nullable<int>
        Console.WriteLine(Describe(age));
        Console.WriteLine("age ?? -1              = " + (age ?? -1));
        Console.WriteLine("GetValueOrDefault()    = " + age.GetValueOrDefault());
        Console.WriteLine("GetValueOrDefault(18)  = " + age.GetValueOrDefault(18));

        // .Value on an empty nullable throws
        try { Console.WriteLine(age.Value); }
        catch (InvalidOperationException) { Console.WriteLine("age.Value -> InvalidOperationException"); }

        age = 30;
        Console.WriteLine(Describe(age));

        // Maths with a null operand gives null ("lifted" operators)
        int? bonus = null;
        int? total = age + bonus;
        Console.WriteLine("30 + null is null? " + (total == null));

        // ?. stops and gives null when the left side is null; ?? supplies a fallback
        string name = null;
        int? length = name?.Length;
        Console.WriteLine("name?.Length is null? " + (length == null) + ", name ?? \"unknown\" = " + (name ?? "unknown"));

        Console.WriteLine("int? is Nullable<int>? " + (typeof(int?) == typeof(Nullable<int>)));
        // Nullable reference types (string?) add no run-time type: they are compiler warnings only.
    }
}
// Time O(1), space O(1).

using System;

class PersonClass { public string Name; public PersonClass(string name) { Name = name; } }
struct PointStruct { public int X; public PointStruct(int x) { X = x; } }
record PersonRecord(string Name, int Age);                    // reference type with value equality
readonly record struct Money(decimal Amount, string Currency); // value type with value equality

class Program
{
    static void Main()
    {
        // class: two objects with the same data are still two different things
        var c1 = new PersonClass("Asha");
        var c2 = new PersonClass("Asha");
        Console.WriteLine("class  Equals: " + c1.Equals(c2));

        // struct: assignment copies, so changing the copy leaves the original alone
        var s1 = new PointStruct(1);
        var s2 = s1;
        s2.X = 99;
        Console.WriteLine("struct copy:   s1.X=" + s1.X + " s2.X=" + s2.X + " Equals: " + s1.Equals(new PointStruct(1)));

        // record: the compiler writes Equals, ==, GetHashCode and ToString from the properties
        var r1 = new PersonRecord("Asha", 30);
        var r2 = new PersonRecord("Asha", 30);
        Console.WriteLine("record ==:     " + (r1 == r2) + ", same object? " + ReferenceEquals(r1, r2));

        // "with" makes a changed copy; the original stays as it was
        var r3 = r1 with { Age = 31 };
        Console.WriteLine("with:          " + r1 + " -> " + r3);

        // record struct: a small value with the same generated members
        var m1 = new Money(10m, "EUR");
        var m2 = new Money(10m, "EUR");
        Console.WriteLine("record struct: " + m1 + " == ? " + (m1 == m2));
    }
}
// Time O(1), space O(1). Record equality compares every property, so it costs O(number of properties).

using System;

[Flags]
enum Permission { None = 0, Read = 1, Write = 2, Delete = 4 }   // one bit each

class Program
{
    // A tuple returns two named values without a new class
    static (int Min, int Max) MinMax(int[] xs)
    {
        int min = xs[0], max = xs[0];
        foreach (int x in xs) { if (x < min) min = x; if (x > max) max = x; }
        return (min, max);
    }

    // Pattern matching tests the type and shape of the data; the first matching arm wins
    static string Describe(object o) => o switch
    {
        int n when n < 0 => "negative int",
        int n => "int " + n,
        string s => "string of length " + s.Length,
        null => "null",
        _ => "something else"            // the discard arm catches everything left
    };

    static void Main()
    {
        // | combines flags, & tests them
        Permission p = Permission.Read | Permission.Write;
        Console.WriteLine("flags: " + p + " = " + (int)p);
        Console.WriteLine("can write? " + p.HasFlag(Permission.Write) + ", can delete? " + ((p & Permission.Delete) != 0));
        p &= ~Permission.Write;          // switch one flag off
        Console.WriteLine("after removing Write: " + p);

        var (min, max) = MinMax(new[] { 4, 9, 2 });   // deconstruct into two locals
        Console.WriteLine("tuple: min=" + min + " max=" + max);

        Console.WriteLine(Describe(-5) + " | " + Describe(7) + " | " + Describe("hello") + " | "
            + Describe(null) + " | " + Describe(3.5));
    }
}
// MinMax is O(n) time, O(1) space; everything else is O(1).

using System;

class Program
{
    static void Main()
    {
        int big = int.MaxValue;

        // Default (unchecked): the result wraps round to the smallest int
        int wrapped = big + 1;
        Console.WriteLine("unchecked: " + big + " + 1 = " + wrapped);

        // checked: the same sum now throws instead of giving a wrong number
        try
        {
            int r = checked(big + 1);
            Console.WriteLine(r);
        }
        catch (OverflowException) { Console.WriteLine("checked:   OverflowException"); }

        // Narrowing casts follow the same rule: 300 does not fit in a byte (0 to 255)
        int n = 300;
        Console.WriteLine("(byte)300 unchecked = " + unchecked((byte)n));
        try { Console.WriteLine(checked((byte)n)); }
        catch (OverflowException) { Console.WriteLine("(byte)300 checked   = OverflowException"); }

        // Math.Round uses banker's rounding: a .5 goes to the nearest even number
        double a = 2.5, b = 3.5;
        Console.WriteLine("Math.Round(2.5) = " + Math.Round(a) + ", Math.Round(3.5) = " + Math.Round(b)
            + ", AwayFromZero(2.5) = " + Math.Round(a, MidpointRounding.AwayFromZero));

        // A cast cuts the fraction off; Convert rounds
        double c = 3.9;
        Console.WriteLine("(int)3.9 = " + (int)c + ", Convert.ToInt32(3.9) = " + Convert.ToInt32(c)
            + ", (int)-3.9 = " + (int)(-c));

        // long has room for the true answer
        long safe = (long)big + 1;
        Console.WriteLine("as long: " + safe);
    }
}
// Time O(1), space O(1). A checked operation costs one extra overflow test.

using System;
using System.Collections.Generic;

class Program
{
    static void Main()
    {
        string a = "FILE.TXT", b = "file.txt";

        // == is ordinal and case-sensitive: it compares the raw characters
        Console.WriteLine("a == b: " + (a == b));

        // Say what you mean with a StringComparison value; no new strings are created
        Console.WriteLine("OrdinalIgnoreCase equal: " + string.Equals(a, b, StringComparison.OrdinalIgnoreCase));

        // Ordinal order uses character codes: every capital letter comes before every small letter
        Console.WriteLine("Compare(apple, Banana) ordinal:     " + Math.Sign(string.Compare("apple", "Banana", StringComparison.Ordinal)));
        Console.WriteLine("Compare(apple, Banana) ignore case: " + Math.Sign(string.Compare("apple", "Banana", StringComparison.OrdinalIgnoreCase)));

        string[] words = { "mango", "Zebra", "apple" };
        Array.Sort(words, StringComparer.Ordinal);
        Console.WriteLine("ordinal sort:     " + string.Join(", ", words));
        Array.Sort(words, StringComparer.OrdinalIgnoreCase);
        Console.WriteLine("ignore-case sort: " + string.Join(", ", words));

        // Searching inside text takes the same option
        string text = "Hello World";
        Console.WriteLine("Contains(\"world\"): " + text.Contains("world")
            + ", IndexOf ignore case found: " + (text.IndexOf("world", StringComparison.OrdinalIgnoreCase) >= 0));

        // A dictionary takes a comparer, so header names match in any casing
        var headers = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        headers["Content-Type"] = "application/json";
        Console.WriteLine("headers[\"content-type\"] = " + headers["content-type"]);
    }
}
// Comparing two strings is O(n) in their length; the dictionary lookup is O(1) on average.

using System;
using System.Collections.Generic;

class PlainPoint { public int X, Y; public PlainPoint(int x, int y) { X = x; Y = y; } }

// Correct: Equals and GetHashCode use the same fields
class Point : IEquatable<Point>
{
    public int X, Y;
    public Point(int x, int y) { X = x; Y = y; }
    public bool Equals(Point other) { return other != null && X == other.X && Y == other.Y; }
    public override bool Equals(object obj) { return Equals(obj as Point); }
    public override int GetHashCode() { unchecked { return X * 397 ^ Y; } }
}

// Broken on purpose: Equals without GetHashCode (the compiler warns about this)
#pragma warning disable 659
class BadPoint
{
    public int X, Y;
    public BadPoint(int x, int y) { X = x; Y = y; }
    public override bool Equals(object obj) { var o = obj as BadPoint; return o != null && X == o.X && Y == o.Y; }
}
#pragma warning restore 659

class Program
{
    static void Main()
    {
        // No overrides: a class is equal only to itself
        var p1 = new PlainPoint(1, 2); var p2 = new PlainPoint(1, 2);
        Console.WriteLine("PlainPoint Equals: " + p1.Equals(p2) + ", ==: " + (p1 == p2));

        var a = new Point(1, 2); var b = new Point(1, 2);
        Console.WriteLine("Point ReferenceEquals: " + ReferenceEquals(a, b) + ", Equals: " + a.Equals(b)
            + ", same hash: " + (a.GetHashCode() == b.GetHashCode()));
        // == was not overloaded on Point, so it still compares references
        Console.WriteLine("Point ==: " + (a == b));

        // A HashSet looks in the bucket chosen by the hash code, then calls Equals
        var good = new HashSet<Point> { a };
        Console.WriteLine("HashSet<Point> finds an equal point: " + good.Contains(b));

        var bad = new HashSet<BadPoint> { new BadPoint(1, 2) };
        Console.WriteLine("BadPoint Equals: " + new BadPoint(1, 2).Equals(new BadPoint(1, 2))
            + ", HashSet<BadPoint> finds it: " + bad.Contains(new BadPoint(1, 2)));
    }
}
// Equals and GetHashCode are O(1) here; a HashSet lookup is O(1) on average.

using System;

struct Vec { public double X, Y; }

class Program
{
    static void AddOne(int x) { x++; }                  // default: works on a copy
    static void AddOneRef(ref int x) { x++; }           // ref: works on the caller's variable

    // out: the method must assign it; handy for "try" methods that return two things
    static bool TryHalf(int n, out int half)
    {
        half = n / 2;
        return n % 2 == 0;
    }

    // in: passed by reference to avoid a copy, but the method may only read it
    static double Length(in Vec v) { return Math.Sqrt(v.X * v.X + v.Y * v.Y); }

    // params: the caller can pass any number of values
    static int Sum(params int[] xs) { int s = 0; foreach (int x in xs) s += x; return s; }

    // optional parameters have defaults; named arguments choose which one to set
    static string Greet(string name, string greeting = "Hello", bool shout = false)
    {
        string text = greeting + ", " + name;
        return shout ? text.ToUpper() + "!" : text;
    }

    static void Main()
    {
        int n = 10;
        AddOne(n);
        Console.WriteLine("after AddOne(n):        " + n);
        AddOneRef(ref n);
        Console.WriteLine("after AddOneRef(ref n): " + n);

        int half;
        bool even = TryHalf(n, out half);
        Console.WriteLine("TryHalf(11): even=" + even + " half=" + half);

        var v = new Vec { X = 3, Y = 4 };
        Console.WriteLine("Length(in v) = " + Length(v));
        Console.WriteLine("Sum() = " + Sum() + ", Sum(1,2,3) = " + Sum(1, 2, 3));
        Console.WriteLine(Greet("Asha"));
        Console.WriteLine(Greet("Asha", shout: true));
        Console.WriteLine(Greet(greeting: "Welcome", name: "Ben"));
    }
}
// Time O(1) apart from Sum, which is O(k) for k arguments.

using System;
using System.Globalization;

class Program
{
    // Run a conversion and report either the number or the exception type
    static string Try(Func<int> convert)
    {
        try { return convert().ToString(); }
        catch (Exception ex) { return ex.GetType().Name; }
    }

    static void Main()
    {
        string[] inputs = { "42", " 7 ", "abc", null, "99999999999" };
        foreach (string s in inputs)
        {
            string shown = s == null ? "null" : "\"" + s + "\"";

            // TryParse never throws: it returns false and sets the result to 0
            int value;
            bool ok = int.TryParse(s, out value);

            Console.WriteLine(shown.PadRight(14)
                + "Parse: " + Try(() => int.Parse(s)).PadRight(22)
                + "TryParse: " + (ok + "/" + value).PadRight(10)
                + "Convert: " + Try(() => Convert.ToInt32(s)));
        }

        // Be explicit about the number format instead of trusting the server's culture
        var european = new NumberFormatInfo { NumberDecimalSeparator = ",", NumberGroupSeparator = "." };
        decimal price = decimal.Parse("1.234,56", NumberStyles.Number, european);
        Console.WriteLine("\"1.234,56\" with comma as decimal separator = " + price.ToString(CultureInfo.InvariantCulture));
    }
}
// Each conversion is O(length of the text).

using System;

class Product
{
    private decimal _price;

    public string Name { get; set; }                 // auto property: the compiler makes the hidden field
    public required string Sku { get; init; }        // must be given at creation, then cannot change
    public string Category { get; init; } = "General";
    public int Quantity { get; private set; }        // anyone can read, only this class can write

    // A full property can validate before it stores the value
    public decimal Price
    {
        get => _price;
        set
        {
            if (value < 0) throw new ArgumentOutOfRangeException(nameof(value));
            _price = value;
        }
    }

    public decimal Total => Price * Quantity;        // computed: no field, worked out on each read

    public void AddStock(int n) { Quantity += n; }
}

class Program
{
    static void Main()
    {
        var p = new Product { Name = "Pen", Sku = "PEN-01", Price = 1.50m };
        p.AddStock(4);
        Console.WriteLine(p.Name + " " + p.Sku + " [" + p.Category + "] " + p.Quantity + " x " + p.Price + " = " + p.Total);

        p.Name = "Blue pen";      // a normal setter
        p.Price = 2m;
        Console.WriteLine("after changes: " + p.Name + ", total = " + p.Total);

        try { p.Price = -1m; }
        catch (ArgumentOutOfRangeException) { Console.WriteLine("Price = -1 rejected by the setter, price is still " + p.Price); }

        // p.Sku = "X";                          // would not compile: init-only
        // p.Quantity = 100;                     // would not compile: private set
        // var q = new Product { Name = "x" };   // would not compile: required Sku is missing
    }
}
// Time O(1), space O(1).

using System;
using System.Collections.Generic;

// Extension methods live in a static class; "this" marks the type they extend
static class StringExtensions
{
    public static bool IsBlank(this string s) => string.IsNullOrWhiteSpace(s);

    public static string Truncate(this string s, int max) =>
        s.Length <= max ? s : s.Substring(0, max) + "...";

    // Works on any sequence, like the LINQ operators do
    public static IEnumerable<T> EveryOther<T>(this IEnumerable<T> source)
    {
        bool take = true;
        foreach (T item in source) { if (take) yield return item; take = !take; }
    }
}

class Program
{
    static int Square(int x) => x * x;          // expression-bodied method: one expression, no braces

    static long Factorial(int n)
    {
        if (n < 0) throw new ArgumentOutOfRangeException(nameof(n));
        return Go(n);

        // Local function: a helper that only this method can see, and it may call itself
        long Go(int k) => k <= 1 ? 1 : k * Go(k - 1);
    }

    static void Main()
    {
        string title = "Extension methods look like instance methods";
        Console.WriteLine(title.Truncate(17));                    // called as if string had the method
        Console.WriteLine(StringExtensions.Truncate(title, 9));   // what the compiler really calls

        string nothing = null;
        Console.WriteLine("null.IsBlank() = " + nothing.IsBlank());   // no exception: it is a static call

        Console.WriteLine("EveryOther: " + string.Join(", ", new[] { 1, 2, 3, 4, 5 }.EveryOther()));
        Console.WriteLine("Square(7) = " + Square(7) + ", Factorial(10) = " + Factorial(10));
    }
}
// Truncate and EveryOther are O(n); Factorial is O(n) time and O(n) stack depth.

using System;
using System.Collections.Concurrent;
using System.Threading.Tasks;

class Counter
{
    public static int Created;                 // one copy shared by every Counter
    public int Number;                         // one copy per object

    // Runs once, automatically, before the type is first used
    static Counter() { Console.WriteLine("static constructor of Counter runs once"); }

    public Counter() { Created++; Number = Created; }
}

sealed class AppConfig
{
    // Lazy<T> creates the object on first use and is thread safe by default
    private static readonly Lazy<AppConfig> _instance = new Lazy<AppConfig>(() => new AppConfig());
    public static AppConfig Instance { get { return _instance.Value; } }

    public string ServiceName { get; private set; }

    // A private constructor stops anyone else from creating a second one
    private AppConfig()
    {
        Console.WriteLine("AppConfig constructor runs");
        ServiceName = "orders-api";
    }
}

class Program
{
    static void Main()
    {
        Console.WriteLine("Main starts");
        var a = new Counter(); var b = new Counter(); var c = new Counter();
        Console.WriteLine("numbers: " + a.Number + ", " + b.Number + ", " + c.Number + "; Counter.Created = " + Counter.Created);

        // Eight parallel callers all get the same object, and the constructor runs once
        var seen = new ConcurrentBag<AppConfig>();
        Parallel.For(0, 8, i => seen.Add(AppConfig.Instance));
        bool allSame = true;
        foreach (AppConfig cfg in seen) allSame &= ReferenceEquals(cfg, AppConfig.Instance);
        Console.WriteLine("8 parallel reads, all the same instance? " + allSame + " (" + AppConfig.Instance.ServiceName + ")");
    }
}
// Reading Instance is O(1); the object is built only once.

using System;
using System.Collections.Generic;

// Abstraction: callers see "an account" with Deposit, Balance and ChargeFee, nothing more
abstract class Account
{
    private decimal _balance;                      // Encapsulation: nobody outside can set this directly
    public string Owner { get; private set; }
    public decimal Balance { get { return _balance; } }

    protected Account(string owner, decimal opening) { Owner = owner; _balance = opening; }

    public void Deposit(decimal amount)
    {
        if (amount <= 0) throw new ArgumentException("Deposit must be positive");
        _balance += amount;                        // the only way in, so the rule always holds
    }

    public abstract decimal MonthlyFee();          // each kind of account decides its own fee
    public void ChargeFee() { _balance -= MonthlyFee(); }
}

// Inheritance: both kinds reuse Owner, Balance, Deposit and ChargeFee
class SavingsAccount : Account
{
    public SavingsAccount(string owner, decimal opening) : base(owner, opening) { }
    public override decimal MonthlyFee() { return 0m; }
}

class CurrentAccount : Account
{
    public CurrentAccount(string owner, decimal opening) : base(owner, opening) { }
    public override decimal MonthlyFee() { return Balance < 1000m ? 5m : 0m; }
}

class Program
{
    static void Main()
    {
        var accounts = new List<Account> { new SavingsAccount("Asha", 500m), new CurrentAccount("Ben", 500m), new CurrentAccount("Chen", 2000m) };

        // Polymorphism: one call, and the object's real type picks the fee rule
        foreach (Account a in accounts)
        {
            a.ChargeFee();
            Console.WriteLine(a.Owner + " (" + a.GetType().Name + "): fee " + a.MonthlyFee() + ", balance " + a.Balance);
        }

        try { accounts[0].Deposit(-50m); }
        catch (ArgumentException ex) { Console.WriteLine("Deposit(-50) rejected: " + ex.Message); }
    }
}
// Time O(n) for n accounts, space O(1) extra.

using System;
using System.Reflection;

class Vehicle
{
    public string Name = "car";                       // everyone
    private string _vin = "VIN-123";                  // this class only
    protected int Wheels = 4;                         // this class and classes that inherit from it
    internal string Plant = "plant-7";                // any code in the same assembly (project)
    protected internal string Batch = "batch-3";      // same assembly OR a derived class anywhere
    private protected string Audit = "audit-1";       // a derived class AND in the same assembly

    public string Inside() { return Name + ", " + _vin + ", " + Wheels + ", " + Plant + ", " + Batch + ", " + Audit; }
}

class Truck : Vehicle
{
    // A derived class sees protected members but not private ones
    public string FromChild() { return Name + ", " + Wheels + ", " + Plant + ", " + Batch + ", " + Audit; }
    // string Bad() { return _vin; }   // would not compile: _vin is private to Vehicle
}

class Program
{
    static void Main()
    {
        var t = new Truck();
        Console.WriteLine("inside the class:   " + t.Inside());
        Console.WriteLine("from a child class: " + t.FromChild());
        // Unrelated code in the same assembly: public, internal and protected internal only
        Console.WriteLine("from other code:    " + t.Name + ", " + t.Plant + ", " + t.Batch);
        // Console.WriteLine(t.Wheels);   // would not compile: protected

        // The compiler stores each access level in the metadata; reflection shows it
        foreach (FieldInfo f in typeof(Vehicle).GetFields(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic))
        {
            string level = f.IsPublic ? "public" : f.IsPrivate ? "private" : f.IsFamily ? "protected"
                : f.IsAssembly ? "internal" : f.IsFamilyOrAssembly ? "protected internal" : "private protected";
            Console.WriteLine("  " + f.Name.PadRight(7) + level);
        }
    }
}
