using System;

class Printer
{
    // Overloads: same name, different parameter lists; the compiler picks one from the argument types
    public string Print(int x) { return "Print(int)"; }
    public string Print(double x) { return "Print(double)"; }
    public string Print(string x) { return "Print(string)"; }
    public string Print(object x) { return "Print(object)"; }
}

class Animal
{
    public virtual string Speak() { return "..."; }
}

class Dog : Animal
{
    // Override: same signature, replaces the parent's version for Dog objects
    public override string Speak() { return "Woof"; }
}

class Program
{
    static void Main()
    {
        var p = new Printer();
        Console.WriteLine("5       -> " + p.Print(5));
        Console.WriteLine("5.0     -> " + p.Print(5.0));
        Console.WriteLine("\"five\"  -> " + p.Print("five"));
        Console.WriteLine("'c'     -> " + p.Print('c'));        // char converts to int implicitly
        Console.WriteLine("null    -> " + p.Print(null));       // the most specific reference type wins

        // The overload is chosen from the declared type, not from what the variable holds
        object boxed = 5;
        Console.WriteLine("object holding 5 -> " + p.Print(boxed));

        // The override is chosen from the real object, whatever the variable type is
        Animal a = new Dog();
        Console.WriteLine("Animal variable holding a Dog says: " + a.Speak());
    }
}
// Overload choice costs nothing at run time; a virtual call is one table lookup, O(1).

