// Abstract class: holds state (Name) and shared code (Describe), leaves Area to the children
abstract class Shape
{
    public string Name { get; }
    protected Shape(string name) { Name = name; }
    public abstract double Area();
    public string Describe() => Name + " with area " + Area().ToString("F2", CultureInfo.InvariantCulture);
}

class Circle : Shape
{
    private readonly double _r;
    public Circle(double r) : base("Circle") { _r = r; }
    public override double Area() => Math.PI * _r * _r;
}

class Rectangle : Shape
{
    private readonly double _w, _h;
    public Rectangle(double w, double h) : base("Rectangle") { _w = w; _h = h; }
    public override double Area() => _w * _h;
}

class Program
{
