    {
        // var s = new Shape("x");   // would not compile: an abstract class cannot be created
        var shapes = new List<Shape> { new Circle(1), new Rectangle(2, 3) };
        ILogger logger = new ConsoleLogger();
        foreach (Shape s in shapes) logger.Log(s.Describe());

        // The default method is reached through the interface type only
        logger.LogError("disk is full");
        // new ConsoleLogger().LogError("x");   // would not compile: not a member of the class
    }
}
