using System;

class Base
{
    public virtual string Who() { return "Base"; }          // children may replace it
    public string Fixed() { return "Base.Fixed"; }          // not virtual: cannot be overridden
}

class Overrider : Base
{
    public override string Who() { return "Overrider"; }    // replaces the method in the object's table
}

class Hider : Base
{
    public new string Who() { return "Hider"; }             // a separate method that only shares the name
}

abstract class Shape
{
    public abstract double Area();                          // no body: children must supply one
}

class Square : Shape
{
    public sealed override double Area() { return 4; }      // sealed: classes below Square cannot override it again
}

sealed class Leaf : Overrider { }                           // sealed class: nothing can inherit from Leaf

class Program
{
    static void Main()
    {
        Base viaOverride = new Overrider();
        Base viaHide = new Hider();

        // override: the real object decides, whatever the variable type is
        Console.WriteLine("Base variable -> Overrider object: " + viaOverride.Who());

        // new: the variable type decides, so the same object gives two answers
        Console.WriteLine("Base variable -> Hider object:     " + viaHide.Who());
        Console.WriteLine("Hider variable -> Hider object:    " + ((Hider)viaHide).Who());

        Shape s = new Square();
        Console.WriteLine("abstract Area() implemented by Square: " + s.Area());
        Console.WriteLine("Leaf inherits the override: " + new Leaf().Who() + ", Fixed(): " + new Leaf().Fixed());
    }
}
// Time O(1): a virtual call is one lookup in the object's method table.

