struct Money
{
    public decimal Amount;
    public Money(decimal amount) { Amount = amount; }
    // Operator overloading is compile-time polymorphism too: + now works for Money
    public static Money operator +(Money a, Money b) { return new Money(a.Amount + b.Amount); }
}

abstract class Shape { public abstract string Draw(); }
class Circle : Shape { public override string Draw() { return "drawing a circle"; } }
class Square : Shape { public override string Draw() { return "drawing a square"; } }

class Program
{
    // 1. Compile-time: overloads, picked by the compiler from the argument types
    static string Add(int a, int b) { return "int " + (a + b); }
    static string Add(double a, double b) { return "double " + (a + b); }
    static string Add(string a, string b) { return "string " + a + b; }

    // 3. Parametric: one method body that works for any type that can be compared
    static T Max<T>(T a, T b) where T : IComparable<T> { return a.CompareTo(b) >= 0 ? a : b; }

    static void Main()
    {
        Console.WriteLine("compile-time: " + Add(1, 2) + " | " + Add(1.5, 2.5) + " | " + Add("ab", "cd"));
        Console.WriteLine("operator +:   " + (new Money(5m) + new Money(7m)).Amount);

        // 2. Run-time: the object's real type picks the override
        var shapes = new List<Shape> { new Circle(), new Square() };
        foreach (Shape s in shapes) Console.WriteLine("run-time:     " + s.Draw());

        Console.WriteLine("generic:      Max(3, 9) = " + Max(3, 9) + ", Max(\"pear\", \"apple\") = " + Max("pear", "apple"));
    }
}
// Overloads and generics are resolved by the compiler; each virtual call is an O(1) table lookup.

