// Second use: keep an interface member off the class's public surface.
class Connection : IDisposable
{
    public bool IsOpen { get; private set; }
    public Connection() { IsOpen = true; }

    public void Close()                     // the name callers should use
    {
        IsOpen = false;
        Console.WriteLine("  connection closed");
    }

    void IDisposable.Dispose() { Close(); } // still there for "using", but hidden from IntelliSense
}

