using System;

// Composition: the notification "has" a channel and a format, so each can change on its own
interface IChannel { string Send(string text); }
class Email : IChannel { public string Send(string text) { return "email: " + text; } }
class Sms : IChannel { public string Send(string text) { return "sms: " + text; } }

interface IFormat { string Apply(string text); }
class Plain : IFormat { public string Apply(string text) { return text; } }
class Shout : IFormat { public string Apply(string text) { return text.ToUpper() + "!"; } }

class Notifier
{
    private readonly IChannel _channel;
    private readonly IFormat _format;
    public Notifier(IChannel channel, IFormat format) { _channel = channel; _format = format; }
    public string Notify(string text) { return _channel.Send(_format.Apply(text)); }
}

// Inheritance would need one class per combination: EmailPlain, EmailShout, SmsPlain, SmsShout...
// 3 channels x 3 formats = 9 classes, and every new option doubles the work.

class Program
{
    static void Main()
    {
        IChannel[] channels = { new Email(), new Sms() };
        IFormat[] formats = { new Plain(), new Shout() };
        int combos = 0;
        foreach (IChannel c in channels)
            foreach (IFormat f in formats)
            {
                Console.WriteLine(new Notifier(c, f).Notify("server is down"));
                combos++;
            }
        Console.WriteLine(combos + " behaviours from " + (channels.Length + formats.Length) + " small classes");

        // Behaviour can even change while the program runs, which inheritance cannot do
        var n = new Notifier(new Sms(), new Plain());
        Console.WriteLine(n.Notify("swap me in tests"));
    }
}
// Time O(1) per notification, space O(1).

