using System;
using System.Collections.Generic;

class Animal { public virtual string Name { get { return "animal"; } } }
class Cat : Animal { public override string Name { get { return "cat"; } } }

class Program
{
    static void Main()
    {
        // Covariance (out): a sequence of Cats can be read as a sequence of Animals
        IEnumerable<Cat> cats = new List<Cat> { new Cat(), new Cat() };
        IEnumerable<Animal> animals = cats;
        foreach (Animal a in animals) Console.WriteLine("read as Animal: " + a.Name);

        // List<T> is not covariant, because it also accepts items (it is not "out" only)
        // List<Animal> wrong = new List<Cat>();   // would not compile

        // Contravariance (in): code that handles any Animal can be used where a handler of Cats is needed
        Action<Animal> printAnimal = a => Console.WriteLine("handler got: " + a.Name);
        Action<Cat> printCat = printAnimal;
        printCat(new Cat());

        // Func is both: it returns its result (out) and takes arguments (in)
        Func<Animal, string> describeAny = a => "a " + a.Name;
        Func<Cat, object> describeCat = describeAny;         // takes a narrower input, returns a wider output
        Console.WriteLine(describeCat(new Cat()));

        // Arrays are covariant too, but unsafe: the check happens at run time
        Animal[] zoo = new Cat[2];
        try { zoo[0] = new Animal(); }
        catch (ArrayTypeMismatchException) { Console.WriteLine("array covariance: ArrayTypeMismatchException at run time"); }

        // Value types do not take part: no reference conversion exists for int to object here
        IEnumerable<int> ints = new List<int> { 1, 2 };
        Console.WriteLine("IEnumerable<int> as IEnumerable<object> allowed? " + (((object)ints) is IEnumerable<object>));
    }
}
// Each conversion is a reference conversion: O(1), no copying.

using System;
using System.Collections;
using System.Collections.Generic;
using System.Linq;

class Program
{
    static void Main()
    {
        // Array: size fixed when created
        int[] arr = new int[3] { 10, 20, 30 };
        Console.WriteLine("array Length = " + arr.Length);
        // arr.Add(40);   // would not compile: arrays have no Add

        // List<T>: grows as needed; capacity doubles when it is full
        var list = new List<int>();
        Console.Write("List capacity while adding:");
        int last = -1;
        for (int i = 1; i <= 10; i++)
        {
            list.Add(i);
            if (list.Capacity != last) { last = list.Capacity; Console.Write(" " + last); }
        }
        Console.WriteLine();
        Console.WriteLine("list Count = " + list.Count + ", Count() = " + list.Count() + " (the property is cheaper)");

        // ArrayList: holds object, so values are boxed and nothing stops mixed types
        var old = new ArrayList();
        old.Add(1);
        old.Add("two");
        old.Add(3.0);
        try
        {
            int sum = 0;
            foreach (object o in old) sum += (int)o;
        }
        catch (InvalidCastException) { Console.WriteLine("ArrayList: mixed types fail only at run time (InvalidCastException)"); }

        // List<string>.Add(5) would not even compile, so the mistake is caught early
        // Inserting at the front shifts every item one place: O(n)
        list.Insert(0, 99);
        Console.WriteLine("after Insert(0, 99): " + string.Join(",", list));
        list.RemoveAt(list.Count - 1);          // removing at the end is O(1)
        Console.WriteLine("after RemoveAt(last): " + string.Join(",", list));
    }
}
// Index access O(1); Add O(1) amortised; Insert/Remove at the front O(n); space O(n).

using System;
using System.Collections.Generic;

// Generic class: written once, works for any T
class Stack<T>
{
    private readonly List<T> _items = new List<T>();
    public int Count { get { return _items.Count; } }
    public void Push(T item) { _items.Add(item); }
    public T Pop()
    {
        if (_items.Count == 0) throw new InvalidOperationException("empty");
        T top = _items[_items.Count - 1];
        _items.RemoveAt(_items.Count - 1);
        return top;
    }
}

interface IEntity { int Id { get; } }
class Customer : IEntity { public int Id { get; set; } public string Name; }

// Constraints say what T must be able to do
class Repository<T> where T : class, IEntity, new()
{
    private readonly Dictionary<int, T> _store = new Dictionary<int, T>();
    public void Add(T item) { _store[item.Id] = item; }       // allowed because T : IEntity
    public T Find(int id) { T found; return _store.TryGetValue(id, out found) ? found : null; }
    public T CreateEmpty() { return new T(); }                // allowed because T : new()
}

class Program
{
    // Generic method with a constraint: T must be comparable
    static T Largest<T>(IEnumerable<T> items) where T : IComparable<T>
    {
        bool first = true; T best = default(T);
        foreach (T x in items) { if (first || x.CompareTo(best) > 0) { best = x; first = false; } }
        return best;
    }

    static void Main()
    {
        var ints = new Stack<int>(); ints.Push(1); ints.Push(2);
        var words = new Stack<string>(); words.Push("a");
        Console.WriteLine("Stack<int> pop = " + ints.Pop() + ", Stack<string> pop = " + words.Pop());
        // ints.Push("x");   // would not compile: type checked at compile time

        Console.WriteLine("Largest of numbers: " + Largest(new[] { 3, 17, 5 }) + ", of words: " + Largest(new[] { "kiwi", "pear", "apple" }));

        var repo = new Repository<Customer>();
        repo.Add(new Customer { Id = 7, Name = "Asha" });
        Console.WriteLine("Find(7) = " + repo.Find(7).Name + ", Find(8) is null: " + (repo.Find(8) == null)
            + ", CreateEmpty Id = " + repo.CreateEmpty().Id);
        Console.WriteLine("default(int) = " + default(int) + ", default(string) is null: " + (default(string) == null));
    }
}
// Push/Pop O(1) amortised; Largest O(n); space O(n) for the stack.

using System;
using System.Collections.Generic;
using System.Diagnostics;

class Program
{
    static void Main()
    {
        int n = 20000;
        var list = new List<int>();
        var set = new HashSet<int>();
        var dict = new Dictionary<int, string>();
        for (int i = 0; i < n; i++) { list.Add(i); set.Add(i); dict[i] = "item" + i; }

        // Count the steps instead of timing them, so the output is the same on every machine
        long listSteps = 0;
        for (int target = n - 100; target < n; target++)
        {
            foreach (int x in list) { listSteps++; if (x == target) break; }     // what List.Contains does
        }
        Console.WriteLine("100 lookups near the end of " + n + " items:");
        Console.WriteLine("  List.Contains: about " + listSteps + " comparisons (O(n) each)");
        Console.WriteLine("  HashSet/Dictionary: about 100 hash lookups (O(1) each)");

        int found = 0;
        for (int target = n - 100; target < n; target++)
        {
            if (set.Contains(target)) found++;
            if (list.Contains(target)) found++;
            if (dict.ContainsKey(target)) found++;
        }
        Console.WriteLine("all three agree, found " + found + " of 300 checks");

        // Sorted collections keep order, at the cost of O(log n) operations
        var sorted = new SortedDictionary<string, int> { { "pear", 3 }, { "apple", 1 }, { "mango", 2 } };
        Console.WriteLine("SortedDictionary order: " + string.Join(", ", sorted.Keys));

        // Queue = first in first out, Stack = last in first out
        var q = new Queue<string>(new[] { "a", "b", "c" });
        var s = new Stack<string>(new[] { "a", "b", "c" });
        Console.WriteLine("Queue.Dequeue = " + q.Dequeue() + ", Stack.Pop = " + s.Pop());
    }
}
// List.Contains O(n); HashSet/Dictionary O(1) average; SortedDictionary O(log n); space O(n).

using System;
using System.Collections.Generic;
using System.Linq;
using System.Linq.Expressions;

class Program
{
    static void Main()
    {
        var table = new List<int> { 5, 12, 8, 30, 3, 21 };

        // IEnumerable + Func: the filter is code, so every row would be fetched and tested here
        int rowsRead = 0;
        IEnumerable<int> inMemory = table.Select(x => { rowsRead++; return x; }).Where(x => x > 10);
        Console.WriteLine("IEnumerable result: " + string.Join(",", inMemory) + " (rows read by the app: " + rowsRead + ")");

        // IQueryable + Expression: the filter is data, so a provider can translate it (EF Core makes SQL)
        IQueryable<int> source = table.AsQueryable();
        Expression<Func<int, bool>> predicate = x => x > 10;
        IQueryable<int> query = source.Where(predicate);
        Console.WriteLine("Expression the provider sees: " + predicate);
        Console.WriteLine("Nothing ran yet; Expression.Body type: " + predicate.Body.NodeType);
        Console.WriteLine("IQueryable result: " + string.Join(",", query));

        // ICollection and IList add counting and index access to plain looping
        IList<int> asList = table;
        ICollection<int> asCollection = table;
        Console.WriteLine("ICollection.Count = " + asCollection.Count + ", IList[3] = " + asList[3]);

        // IEnumerable is only "give me the next item": no Count, no index
        IEnumerable<int> forwardOnly = table.Where(x => x < 10);
        using (IEnumerator<int> e = forwardOnly.GetEnumerator())
        {
            while (e.MoveNext()) Console.Write("next=" + e.Current + " ");
        }
        Console.WriteLine();
    }
}
// In memory, Where is O(n). A database provider could turn the same expression into an indexed WHERE.

using System;
using System.Collections.Generic;
using System.Linq;

class Employee { public string Name; public int DeptId; public decimal Salary; }
class Dept { public int Id; public string Title; }

class Program
{
    static void Main()
    {
        var staff = new List<Employee>
        {
            new Employee { Name = "Asha", DeptId = 1, Salary = 50 },
            new Employee { Name = "Ben", DeptId = 2, Salary = 40 },
            new Employee { Name = "Chen", DeptId = 1, Salary = 70 },
        };
        var depts = new List<Dept> { new Dept { Id = 1, Title = "Eng" }, new Dept { Id = 2, Title = "Ops" }, new Dept { Id = 3, Title = "HR" } };

        // Deferred execution: the query is only a recipe until something reads it
        var rich = staff.Where(e => e.Salary > 45);
        staff.Add(new Employee { Name = "Dee", DeptId = 2, Salary = 90 });      // added AFTER the query was written
        Console.WriteLine("Where (deferred) sees Dee: " + string.Join(",", rich.Select(e => e.Name)));
        var snapshot = staff.Where(e => e.Salary > 45).ToList();                // ToList runs it now
        staff.Add(new Employee { Name = "Eve", DeptId = 1, Salary = 99 });
        Console.WriteLine("ToList snapshot count: " + snapshot.Count + ", live query count: " + rich.Count());

        // GroupBy: one group per key
        foreach (var g in staff.GroupBy(e => e.DeptId))
            Console.WriteLine("dept " + g.Key + ": " + string.Join("+", g.Select(e => e.Name)) + " total " + g.Sum(e => e.Salary));

        // Join: only matching pairs (an inner join), so HR is missing
        var joined = staff.Join(depts, e => e.DeptId, d => d.Id, (e, d) => e.Name + "@" + d.Title);
        Console.WriteLine("Join: " + string.Join(", ", joined));

        // Left join: group the matches, then keep departments with none
        foreach (var d in depts)
            Console.WriteLine("left join " + d.Title + ": " + staff.Count(e => e.DeptId == d.Id) + " staff");

        // SelectMany flattens lists of lists into one list
        var tags = new List<List<string>> { new List<string> { "a", "b" }, new List<string> { "c" } };
        Console.WriteLine("SelectMany: " + string.Join(",", tags.SelectMany(t => t)));
    }
}
// Where/Select O(n); GroupBy and Join O(n) using hash tables; space O(n).

using System;
using System.Collections.Generic;
using System.Linq;

class Program
{
    static int reads;                                       // counts how many items the sequence produces

    static IEnumerable<int> Numbers(int n)
    {
        for (int i = 1; i <= n; i++) { reads++; yield return i; }
    }

    static void Main()
    {
        // Any() stops at the first match; Count() > 0 walks everything
        reads = 0; bool a = Numbers(1000).Any(x => x > 0);
        Console.WriteLine("Any:       " + a + " after " + reads + " item(s) read");
        reads = 0; bool c = Numbers(1000).Count(x => x > 0) > 0;
        Console.WriteLine("Count > 0: " + c + " after " + reads + " items read");

        // Take stops early too
        reads = 0; var firstThree = Numbers(1000).Take(3).ToList();
        Console.WriteLine("Take(3):   " + string.Join(",", firstThree) + " after " + reads + " items read");

        // A lazy query used twice runs twice
        reads = 0; var lazy = Numbers(5).Where(x => x % 2 == 0);
        int first = lazy.Count(); int second = lazy.Count();
        Console.WriteLine("lazy used twice: reads = " + reads + " (the source was walked two times)");
        reads = 0; var cached = Numbers(5).Where(x => x % 2 == 0).ToList();
        int third = cached.Count; int fourth = cached.Count;
        Console.WriteLine("ToList once:     reads = " + reads + " (counted " + third + " and " + fourth + " from memory)");

        // Filter first, sort second: fewer items to sort
        var data = Enumerable.Range(1, 20).Reverse().ToList();
        Console.WriteLine("Where then OrderBy: " + string.Join(",", data.Where(x => x <= 5).OrderBy(x => x)));
        Console.WriteLine("(sorting 5 items instead of 20)");
    }
}
// Any is O(1) best case; Count(predicate) is O(n); OrderBy is O(m log m) for m items left after Where.

using System;
using System.Collections.Generic;
using System.Linq;

static class MyLinq
{
    // yield return hands back one item at a time and pauses until the caller asks for the next
    public static IEnumerable<T> MyWhere<T>(this IEnumerable<T> source, Func<T, bool> keep)
    {
        foreach (T item in source)
            if (keep(item)) yield return item;
    }

    public static IEnumerable<TOut> MySelect<T, TOut>(this IEnumerable<T> source, Func<T, TOut> map)
    {
        foreach (T item in source) yield return map(item);
    }

    public static IEnumerable<T> MyTake<T>(this IEnumerable<T> source, int count)
    {
        if (count <= 0) yield break;                 // yield break ends the sequence
        int taken = 0;
        foreach (T item in source)
        {
            yield return item;
            if (++taken == count) yield break;       // stop early: do not ask the source for more
        }
    }
}

class Program
{
    static IEnumerable<int> Naturals()
    {
        int n = 1;
        while (true)
        {
            Console.Write("[make " + n + "] ");
            yield return n++;                        // an endless sequence is fine because it is lazy
        }
    }

    static void Main()
    {
        // Nothing runs until the foreach asks for items; each item flows through the whole chain
        var query = Naturals().MyWhere(x => x % 2 == 0).MySelect(x => x * x).MyTake(3);
        Console.WriteLine("query built, nothing has run yet");
        foreach (int v in query) Console.Write("-> " + v + "  ");
        Console.WriteLine();

        // Same answer as the built-in operators
        var builtIn = Naturals().Where(x => x % 2 == 0).Select(x => x * x).Take(3).ToList();
        Console.WriteLine();
        Console.WriteLine("built-in LINQ gives: " + string.Join(",", builtIn));
    }
}
// Each operator is O(1) per item and keeps O(1) memory; the chain does only the work asked for.

using System;
using System.Collections.Generic;

// A cut-down version of Dictionary: hash -> bucket index -> short chain -> Equals
class MiniDict<TKey, TValue>
{
    private class Entry { public TKey Key; public TValue Value; public Entry Next; }
    private Entry[] _buckets = new Entry[4096];   // fixed size keeps the demo short (the real one resizes)
    private readonly IEqualityComparer<TKey> _cmp;
    public int Count;
    public int Comparisons;                                  // counts Equals calls, to show the cost

    public MiniDict(IEqualityComparer<TKey> cmp) { _cmp = cmp; }

    private int IndexOf(TKey key) { return (_cmp.GetHashCode(key) & 0x7FFFFFFF) % _buckets.Length; }

    public void Add(TKey key, TValue value)
    {
        int i = IndexOf(key);
        _buckets[i] = new Entry { Key = key, Value = value, Next = _buckets[i] };
        Count++;
    }

    public bool TryGet(TKey key, out TValue value)
    {
        for (Entry e = _buckets[IndexOf(key)]; e != null; e = e.Next)
        {
            Comparisons++;
            if (_cmp.Equals(e.Key, key)) { value = e.Value; return true; }
        }
        value = default(TValue);
        return false;
    }
}

class BadHash : IEqualityComparer<int>
{
    public bool Equals(int a, int b) { return a == b; }
    public int GetHashCode(int x) { return 1; }               // every key lands in the same bucket
}

class Program
{
    static int Run(IEqualityComparer<int> cmp, string label)
    {
        var d = new MiniDict<int, string>(cmp);
        for (int i = 0; i < 2000; i++) d.Add(i, "v" + i);
        string v; int hits = 0;
        for (int i = 0; i < 2000; i++) if (d.TryGet(i, out v)) hits++;
        Console.WriteLine(label + ": found " + hits + " keys using " + d.Comparisons + " Equals calls");
        return d.Comparisons;
    }

    static void Main()
    {
        Run(EqualityComparer<int>.Default, "good hash");
        Run(new BadHash(), "bad hash ");
    }
}
// Good hash: O(1) average per lookup. All keys equal hash: O(n) per lookup, O(n^2) overall.

using System;
using System.Collections.Generic;

delegate int Operation(int a, int b);                       // a custom delegate type

class Program
{
    static int Add(int a, int b) { return a + b; }

    static void Main()
    {
        // A delegate is a variable that holds a method
        Operation op = Add;
        Console.WriteLine("custom delegate: " + op(2, 3));

        Func<int, int, int> multiply = (a, b) => a * b;      // Func: takes inputs, returns a result (last type)
        Action<string> shout = s => Console.WriteLine(s.ToUpper());   // Action: takes inputs, returns nothing
        Predicate<int> isEven = n => n % 2 == 0;             // Predicate: takes one input, returns bool
        Console.WriteLine("Func: " + multiply(4, 5));
        shout("action ran");
        Console.WriteLine("Predicate: " + isEven(10) + ", " + isEven(7));

        // Passing a method as an argument: the caller decides what "keep" means
        var numbers = new List<int> { 1, 2, 3, 4, 5, 6 };
        Console.WriteLine("FindAll with Predicate: " + string.Join(",", numbers.FindAll(isEven)));

        // Multicast: += adds methods, and calling the delegate calls all of them in order
        Action<string> log = s => Console.WriteLine("  console: " + s);
        log += s => Console.WriteLine("  audit:   " + s);
        Console.WriteLine("handlers: " + log.GetInvocationList().Length);
        log("saved");

        // A null delegate has no handlers; ?.Invoke checks for that in one step
        Action<string> nobody = null;
        nobody?.Invoke("this is skipped without an exception");

        // With a return value, a multicast delegate gives back only the last result
        Func<int> counter = () => 1;
        counter += () => 2;
        Console.WriteLine("multicast Func returns the last: " + counter());
    }
}
// Calling a delegate is O(1) per handler; a multicast delegate with k handlers costs O(k).

