using System;
using System.Collections.Generic;

class Program
{
    static void Main()
    {
        // A closure captures the variable itself, not a copy of its value
        int x = 1;
        Action show = () => Console.WriteLine("closure sees x = " + x);
        x = 99;                                    // changed after the lambda was written
        show();                                    // prints 99

        // for loop: ONE variable i for the whole loop, shared by every lambda
        var forActions = new List<Action>();
        for (int i = 0; i < 3; i++) forActions.Add(() => Console.Write(i + " "));
        Console.Write("for loop, captured i:      ");
        foreach (Action a in forActions) a();       // all see the final value, 3
        Console.WriteLine();

        // fix: copy into a variable declared inside the loop, so each pass gets a new one
        var fixedActions = new List<Action>();
        for (int i = 0; i < 3; i++) { int copy = i; fixedActions.Add(() => Console.Write(copy + " ")); }
        Console.Write("for loop, copy per pass:    ");
        foreach (Action a in fixedActions) a();
        Console.WriteLine();

        // foreach (C# 5 onwards) creates a new variable for each item, so it is already correct
        var each = new List<Action>();
        foreach (int n in new[] { 10, 20, 30 }) each.Add(() => Console.Write(n + " "));
        Console.Write("foreach, captured variable: ");
        foreach (Action a in each) a();
        Console.WriteLine();

        // A counter that survives between calls because the closure keeps its own variable
        Func<int> MakeCounter()
        {
            int count = 0;
            return () => ++count;
        }
        var c1 = MakeCounter(); var c2 = MakeCounter();
        Console.WriteLine("counter 1: " + c1() + "," + c1() + "," + c1() + "   counter 2: " + c2());
    }
}
// Each call is O(1); every captured variable lives on the heap in a compiler-made object.

using System;
using System.Collections.Generic;
using System.Linq;

class Program
{
    static void Main()
    {
        var numbers = new List<int> { 5, 2, 8, 1 };

        // Anonymous method (C# 2): the older "delegate" keyword form
        Func<int, int> oldWay = delegate (int n) { return n * 2; };

        // Lambda: short form; an expression body or a statement body in braces
        Func<int, int> double1 = n => n * 2;
        Func<int, int> double2 = n => { int result = n * 2; return result; };
        Console.WriteLine("anonymous " + oldWay(4) + ", lambda " + double1(4) + ", statement lambda " + double2(4));

        // Lambdas are everywhere in LINQ
        Console.WriteLine("sorted descending: " + string.Join(",", numbers.OrderByDescending(n => n)));

        // Local function: a named helper, which can call itself, declared after it is used
        Console.WriteLine("5! = " + Factorial(5));
        long Factorial(int k) { return k <= 1 ? 1 : k * Factorial(k - 1); }

        // A lambda cannot refer to itself unless declared first
        Func<int, long> fact = null;
        fact = k => k <= 1 ? 1 : k * fact(k - 1);
        Console.WriteLine("lambda 5! = " + fact(5));

        // Method group conversion: a method name can stand for the lambda
        string[] words = { "10", "20", "30" };
        Console.WriteLine("sum with method group: " + words.Select(int.Parse).Sum());

        // Natural type (C# 10): var works for a lambda when the parameter types are written
        var add = (int a, int b) => a + b;
        Console.WriteLine("natural type: " + add.GetType().Name + " -> " + add(2, 3));
    }
}
// Each of these is O(1) to call; Factorial is O(n) time and recursion depth.

using System;
using System.Linq.Expressions;

class Product { public string Name; public decimal Price; }

class Program
{
    // Walk the tree and write it as a SQL-like text: a toy version of what EF Core does
    static string ToSql(Expression e)
    {
        var bin = e as BinaryExpression;
        if (bin != null)
        {
            string op = bin.NodeType == ExpressionType.GreaterThan ? ">" : bin.NodeType == ExpressionType.Equal ? "=" : bin.NodeType == ExpressionType.AndAlso ? "AND" : "?";
            return "(" + ToSql(bin.Left) + " " + op + " " + ToSql(bin.Right) + ")";
        }
        var member = e as MemberExpression;
        if (member != null) return member.Member.Name;
        var constant = e as ConstantExpression;
        if (constant != null) return constant.Value is string ? "'" + constant.Value + "'" : Convert.ToString(constant.Value);
        return "?";
    }

    static void Main()
    {
        // Func is code you can only run; Expression<Func> is a tree you can read
        Func<Product, bool> asCode = p => p.Price > 10m;
        Expression<Func<Product, bool>> asData = p => p.Price > 10m && p.Name == "Pen";

        Console.WriteLine("tree:   " + asData);
        Console.WriteLine("root:   " + asData.Body.NodeType);
        Console.WriteLine("as SQL: WHERE " + ToSql(asData.Body));

        // Compile turns the tree back into a real delegate (slow to do, so keep the result)
        Func<Product, bool> compiled = asData.Compile();
        var pen = new Product { Name = "Pen", Price = 12m };
        var pad = new Product { Name = "Pad", Price = 12m };
        Console.WriteLine("compiled on Pen: " + compiled(pen) + ", on Pad: " + compiled(pad) + ", plain func on Pen: " + asCode(pen));

        // Build a tree by hand: x => x * 2
        ParameterExpression x = Expression.Parameter(typeof(int), "x");
        var doubler = Expression.Lambda<Func<int, int>>(Expression.Multiply(x, Expression.Constant(2)), x).Compile();
        Console.WriteLine("hand-built x => x * 2, with 21: " + doubler(21));
    }
}
// Walking the tree is O(nodes). Compile() is expensive (milliseconds) but the compiled delegate runs at normal speed.

using System;
using System.IO;

class Program
{
    // finally runs even when the try block returns
    static string WithReturn()
    {
        try { return "returned from try"; }
        finally { Console.WriteLine("  finally runs before the method really returns"); }
    }

    static void Risky(int kind)
    {
        try
        {
            Console.WriteLine("  try: start");
            if (kind == 1) throw new ArgumentNullException("name");
            if (kind == 2) throw new FileNotFoundException("missing.txt");
            if (kind == 3) throw new InvalidOperationException("bad state");
            Console.WriteLine("  try: finished normally");
        }
        catch (ArgumentException ex)                     // ArgumentNullException is a kind of ArgumentException
        {
            Console.WriteLine("  catch ArgumentException: " + ex.GetType().Name);
        }
        catch (IOException ex)                           // more specific catches must come first
        {
            Console.WriteLine("  catch IOException: " + ex.GetType().Name);
        }
        catch (Exception ex)                             // the last, general catch
        {
            Console.WriteLine("  catch Exception: " + ex.Message);
        }
        finally
        {
            Console.WriteLine("  finally: cleanup");
        }
    }

    static void Main()
    {
        for (int kind = 0; kind <= 3; kind++)
        {
            Console.WriteLine("case " + kind + ":");
            Risky(kind);
        }
        Console.WriteLine(WithReturn());

        // Walk up the hierarchy: FileNotFoundException -> IOException -> SystemException -> Exception
        Type t = typeof(FileNotFoundException);
        string chain = t.Name;
        while (t.BaseType != null && t != typeof(Exception)) { t = t.BaseType; chain += " -> " + t.Name; }
        Console.WriteLine(chain);
    }
}
// A throw is slow (microseconds to milliseconds) compared with a normal return: do not use exceptions for ordinary flow.

using System;
using System.Runtime.CompilerServices;
using System.Runtime.ExceptionServices;

class Program
{
    [MethodImpl(MethodImplOptions.NoInlining)] static void Save() { throw new InvalidOperationException("disk full"); }       // the real origin

    [MethodImpl(MethodImplOptions.NoInlining)] static void WithThrow()   { try { Save(); } catch (Exception) { throw; } }      // keeps the original trace
    [MethodImpl(MethodImplOptions.NoInlining)] static void WithThrowEx() { try { Save(); } catch (Exception ex) { throw ex; } } // trace restarts here
    [MethodImpl(MethodImplOptions.NoInlining)] static void Wrapped()     { try { Save(); } catch (Exception ex) { throw new ApplicationException("order failed", ex); } }

    // Show the method names found in the stack trace
    static string Frames(Exception ex)
    {
        var names = new System.Collections.Generic.List<string>();
        foreach (string line in ex.StackTrace.Split('\n'))
        {
            string l = line.Trim();
            int at = l.IndexOf("Program.");
            if (at >= 0) { int end = l.IndexOf('(', at); names.Add(l.Substring(at + 8, end - at - 8)); }
        }
        return string.Join(" <- ", names);
    }

    static void Main()
    {
        try { WithThrow(); }   catch (Exception ex) { Console.WriteLine("throw;     frames: " + Frames(ex)); }
        try { WithThrowEx(); } catch (Exception ex) { Console.WriteLine("throw ex;  frames: " + Frames(ex)); }

        try { Wrapped(); }
        catch (Exception ex)
        {
            Console.WriteLine("wrapped:   " + ex.Message + " | inner: " + ex.InnerException.Message);
            Console.WriteLine("           inner frames: " + Frames(ex.InnerException));
        }

        // Rethrow later, from outside the catch block, and still keep the original trace
        ExceptionDispatchInfo captured = null;
        try { Save(); } catch (Exception ex) { captured = ExceptionDispatchInfo.Capture(ex); }
        try { captured.Throw(); }
        catch (Exception ex) { Console.WriteLine("Capture().Throw(): " + Frames(ex)); }
    }
}
// Time O(1) per throw plus the cost of building a stack trace, which grows with the call depth.

using System;

// Good reason for a custom exception: callers need to react to this case and need data about it
class InsufficientFundsException : Exception
{
    public decimal Balance { get; private set; }
    public decimal Requested { get; private set; }

    public InsufficientFundsException(decimal balance, decimal requested, Exception inner = null)
        : base("Balance " + balance + " is less than the " + requested + " requested.", inner)
    {
        Balance = balance; Requested = requested;
    }
}

// Expected outcome: use a result object, not an exception
class Result
{
    public bool Ok { get; private set; }
    public string Error { get; private set; }
    public static Result Success() { return new Result { Ok = true }; }
    public static Result Fail(string error) { return new Result { Ok = false, Error = error }; }
}

class Account
{
    public decimal Balance = 100m;

    public void Withdraw(decimal amount)
    {
        if (amount <= 0) throw new ArgumentOutOfRangeException("amount", "must be positive");   // a bug in the caller
        if (amount > Balance) throw new InsufficientFundsException(Balance, amount);
        Balance -= amount;
    }
}

class Users
{
    private readonly System.Collections.Generic.HashSet<string> _emails = new System.Collections.Generic.HashSet<string>();
    public Result Register(string email)
    {
        return _emails.Add(email) ? Result.Success() : Result.Fail("email already taken");   // normal business case
    }
}

class Program
{
    static void Main()
    {
        var acc = new Account();
        try { acc.Withdraw(250m); }
        catch (InsufficientFundsException ex)
        {
            Console.WriteLine("caught: " + ex.Message + " (short by " + (ex.Requested - ex.Balance) + ")");
        }
        try { acc.Withdraw(-5m); }
        catch (ArgumentOutOfRangeException ex) { Console.WriteLine("caller bug: " + ex.ParamName); }

        var users = new Users();
        Console.WriteLine("first register:  " + users.Register("a@example.com").Ok);
        Result again = users.Register("a@example.com");
        Console.WriteLine("second register: " + again.Ok + " (" + again.Error + ")");
    }
}
// Time O(1). A thrown exception costs far more than returning a Result.

using System;
using System.Collections.Generic;
using System.IO;

class Program
{
    static readonly List<string> Log = new List<string>();

    // Guard clauses: fail early with the right built-in exception, and say which argument is wrong
    static decimal Price(string item, int qty)
    {
        if (string.IsNullOrWhiteSpace(item)) throw new ArgumentException("item is required", "item");
        if (qty <= 0) throw new ArgumentOutOfRangeException("qty", qty, "must be positive");
        return 2.5m * qty;
    }

    // Catch only what you can handle here; cleanup goes in finally or using
    static string ReadOrDefault(string path)
    {
        try { return File.ReadAllText(path); }
        catch (FileNotFoundException) { return "(default)"; }       // expected and handled: no log, no rethrow
    }

    static void Layer3() { throw new InvalidOperationException("stock service unavailable"); }
    static void Layer2() { Layer3(); }                              // does not catch: nothing useful to add
    static void Layer1() { Layer2(); }

    // Catch with a filter: only the exceptions that match are handled; others pass through untouched
    static bool TryOnce(Action work)
    {
        try { work(); return true; }
        catch (InvalidOperationException ex) when (ex.Message.Contains("unavailable"))
        {
            Log.Add("retryable: " + ex.Message);
            return false;
        }
    }

    static void Main()
    {
        try { Price("", 1); } catch (ArgumentException ex) { Console.WriteLine("guard 1: " + ex.ParamName); }
        try { Price("pen", 0); } catch (ArgumentOutOfRangeException ex) { Console.WriteLine("guard 2: " + ex.ParamName + " = " + ex.ActualValue); }
        Console.WriteLine("price = " + Price("pen", 4));
        Console.WriteLine("missing file -> " + ReadOrDefault("no-such-file.txt"));

        Console.WriteLine("filter handled it: " + !TryOnce(Layer1) + ", log: " + string.Join("; ", Log));

        // The single outer handler: log once, with the full details
        try { Layer1(); }
        catch (Exception ex) { Console.WriteLine("global handler logs once: " + ex.GetType().Name + " - " + ex.Message); }
    }
}
// Each guard is O(1); the cost of a throw is paid only on the failure path.

using System;
using System.Collections.Generic;

class Context
{
    public string Path;
    public int StatusCode = 200;
    public string Body = "";
}

class NotFoundException : Exception { public NotFoundException(string m) : base(m) { } }
class ValidationException : Exception { public ValidationException(string m) : base(m) { } }

// A request delegate and a middleware, built the way ASP.NET Core does it
delegate void RequestDelegate(Context ctx);

class Pipeline
{
    private readonly List<Func<RequestDelegate, RequestDelegate>> _parts = new List<Func<RequestDelegate, RequestDelegate>>();
    public void Use(Func<RequestDelegate, RequestDelegate> middleware) { _parts.Add(middleware); }

    public RequestDelegate Build(RequestDelegate endpoint)
    {
        RequestDelegate app = endpoint;
        for (int i = _parts.Count - 1; i >= 0; i--) app = _parts[i](app);    // the first added wraps all the others
        return app;
    }
}

class Program
{
    static void Main()
    {
        var log = new List<string>();
        var pipeline = new Pipeline();

        // The exception handler goes first, so it surrounds everything after it
        pipeline.Use(next => ctx =>
        {
            try { next(ctx); }
            catch (NotFoundException ex) { ctx.StatusCode = 404; ctx.Body = "{\"title\":\"Not found\",\"detail\":\"" + ex.Message + "\"}"; }
            catch (ValidationException ex) { ctx.StatusCode = 400; ctx.Body = "{\"title\":\"Invalid request\",\"detail\":\"" + ex.Message + "\"}"; }
            catch (Exception ex)
            {
                log.Add("ERROR " + ex.GetType().Name + ": " + ex.Message);       // logged once, with details
                ctx.StatusCode = 500; ctx.Body = "{\"title\":\"Server error\"}";   // nothing internal goes to the caller
            }
        });

        // The endpoint has no try/catch at all
        RequestDelegate endpoint = ctx =>
        {
            if (ctx.Path == "/orders/1") ctx.Body = "{\"id\":1}";
            else if (ctx.Path == "/orders/99") throw new NotFoundException("order 99 does not exist");
            else if (ctx.Path == "/orders/new") throw new ValidationException("quantity must be positive");
            else throw new InvalidOperationException("database timeout");
        };

        RequestDelegate app = pipeline.Build(endpoint);
        foreach (string path in new[] { "/orders/1", "/orders/99", "/orders/new", "/orders/crash" })
        {
            var ctx = new Context { Path = path };
            app(ctx);
            Console.WriteLine(path.PadRight(14) + ctx.StatusCode + " " + ctx.Body);
        }
        Console.WriteLine("log: " + string.Join(" | ", log));
    }
}
// Each request is O(number of middleware); exceptions are paid for only on failure.
